import argparse
import json
import math
import statistics
from collections import Counter
from pathlib import Path

import psycopg
from psycopg.rows import dict_row


# --------------------------------------------------
# Configuration
# --------------------------------------------------

# Connect only to our isolated benchmark database
DATABASE_URL = "postgresql:///rush_benchmark"

# Directory containing results generated by locustfile.py
RESULTS_DIR = Path(__file__).resolve().parent / "results"


# --------------------------------------------------
# Helper functions
# --------------------------------------------------

# Read previously stored benchmark results
def load_json(path):

    return json.loads(
        path.read_text(encoding="utf-8")
    )


# Calculate a percentile using the nearest-rank method
def percentile(values, percent):

    if not values:
        return None

    # Arrange response times from fastest to slowest
    ordered = sorted(values)

    # Find the position corresponding to the requested percentile
    index = max(
        0,
        math.ceil(len(ordered) * percent / 100) - 1,
    )

    return ordered[index]


# Calculate latency metrics for a benchmark phase
def latency_metrics(records):

    # Extract response times measured by our load generator
    latencies = [
        record["latency_ms"]
        for record in records
    ]

    if not latencies:
        return {}

    return {

        # Average request latency
        "mean_ms": statistics.mean(latencies),

        # Median latency
        "p50_ms": percentile(latencies, 50),

        # Response time experienced by 95% of requests
        "p95_ms": percentile(latencies, 95),

        # Response time experienced by 99% of requests
        "p99_ms": percentile(latencies, 99),

        # Slowest and fastest requests
        "max_ms": max(latencies),
        "min_ms": min(latencies),
    }


# --------------------------------------------------
# PostgreSQL capacity state
# --------------------------------------------------

# Retrieve campaign capacity and durable lease information
def load_capacity_state():

    # dict_row allows us to access columns using their names
    with psycopg.connect(
        DATABASE_URL,
        row_factory=dict_row,
    ) as connection:

        with connection.cursor() as cursor:

            # LEFT JOIN retains campaigns that never received a lease
            cursor.execute("""
                SELECT
                    c.id,
                    c.name,
                    c.capacity,
                    c.remaining_unleased_capacity,
                    c.status,

                    COALESCE(
                        SUM(l.granted_units), 0
                    ) AS granted_units,

                    COUNT(l.lease_request_id) AS lease_count,

                    COUNT(DISTINCT l.worker_id) AS worker_count

                FROM campaigns c

                LEFT JOIN campaign_leases l
                    ON c.id = l.campaign_id

                GROUP BY c.id
                ORDER BY c.id
            """)

            return cursor.fetchall()


# --------------------------------------------------
# Pod correctness audit
# --------------------------------------------------

# Validate every returned advertisement pod
def audit_pods(records, manifest, violations):

    # Track commercial allocations per campaign
    allocations = Counter()

    # Track how the requested ad break duration was utilized
    commercial_seconds = 0
    house_seconds = 0
    unfilled_seconds = 0

    successful_requests = 0

    # Track ALLOCATED, NO_FILL and DEGRADED_FALLBACK responses
    statuses = Counter()

    for record in records:

        request = record["request"]
        response = record["response"]

        request_id = request["request_id"]

        # Record failed requests without attempting to audit their pods
        if (
            record["status_code"] != 200
            or record["error"] is not None
            or not response
        ):
            violations.append(
                f"{request_id}: unsuccessful API response"
            )
            continue

        successful_requests += 1

        # Count how often each decision status was returned
        statuses[response["status"]] += 1

        # Ensure the response belongs to the original request
        if response["request_id"] != request_id:
            violations.append(
                f"{request_id}: incorrect response request ID"
            )

        # Track campaigns already selected for this particular pod
        selected_campaigns = set()

        # Track competitive groups already present in the pod
        competitive_groups = set()

        total_duration = 0

        # Validate each advertisement slot independently
        for slot in response["slots"]:

            duration = slot["duration_seconds"]
            total_duration += duration

            if duration <= 0:
                violations.append(
                    f"{request_id}: invalid slot duration"
                )

            # House ads do not consume commercial campaign capacity
            if slot["source"] == "HOUSE":

                house_seconds += duration

                # House slots must not reference commercial campaigns
                if slot["campaign_id"] is not None:
                    violations.append(
                        f"{request_id}: invalid house slot"
                    )

                continue

            # Reject unrecognized advertisement sources
            if slot["source"] != "COMMERCIAL":

                violations.append(
                    f"{request_id}: unknown slot source"
                )

                continue

            campaign_id = slot["campaign_id"]

            # Count commercial allocations and advertisement duration
            allocations[campaign_id] += 1
            commercial_seconds += duration

            # Retrieve the original campaign configuration
            campaign = manifest.get(campaign_id)

            if campaign is None:

                violations.append(
                    f"{request_id}: unknown campaign {campaign_id}"
                )

                continue


            # ------------------------------------------
            # Campaign eligibility checks
            # ------------------------------------------

            # Only active campaigns should be allocated
            if campaign["status"] != "ACTIVE":
                violations.append(
                    f"{request_id}: inactive campaign"
                )

            # Campaign must target the viewer's region
            if request["region"] not in campaign["regions"]:
                violations.append(
                    f"{request_id}: invalid region targeting"
                )

            # Campaign must support the viewer's device
            if request["device"] not in campaign["devices"]:
                violations.append(
                    f"{request_id}: invalid device targeting"
                )

            # Campaign must target the viewer's subscription tier
            if (
                request["subscription_tier"]
                not in campaign["subscription_tiers"]
            ):
                violations.append(
                    f"{request_id}: invalid tier targeting"
                )

            # Returned slot duration must match campaign configuration
            if duration != campaign["duration_seconds"]:
                violations.append(
                    f"{request_id}: incorrect campaign duration"
                )


            # ------------------------------------------
            # Pod-level constraints
            # ------------------------------------------

            # The same campaign cannot appear twice in a pod
            if campaign_id in selected_campaigns:
                violations.append(
                    f"{request_id}: duplicate campaign in pod"
                )

            selected_campaigns.add(campaign_id)

            group = campaign["competitive_group"]

            # Campaigns without a competitive group are unrestricted
            if group is not None:

                # Competing campaigns cannot appear in the same pod
                if group in competitive_groups:
                    violations.append(
                        f"{request_id}: competitive exclusion violation"
                    )

                competitive_groups.add(group)


        # ----------------------------------------------
        # Validate the complete pod duration
        # ----------------------------------------------

        unfilled = response["unfilled_duration_seconds"]

        unfilled_seconds += unfilled

        if unfilled < 0:
            violations.append(
                f"{request_id}: negative unfilled duration"
            )

        # Sum of slot durations must match the reported filled duration
        if total_duration != response["filled_duration_seconds"]:
            violations.append(
                f"{request_id}: incorrect filled duration"
            )

        # Filled and unfilled duration must equal the requested break
        if (
            total_duration + unfilled
            != request["break_duration_seconds"]
        ):
            violations.append(
                f"{request_id}: invalid total pod duration"
            )

    # Return the accumulated results for this benchmark phase
    return {
        "successful_requests": successful_requests,
        "allocations": dict(allocations),
        "commercial_seconds": commercial_seconds,
        "house_seconds": house_seconds,
        "unfilled_seconds": unfilled_seconds,
        "statuses": dict(statuses),
    }


# --------------------------------------------------
# Idempotency audit
# --------------------------------------------------

# Verify that replaying requests does not create new allocations
def audit_replays(primary, replay, snapshots, violations):

    # Map each original request ID to its original response
    original_responses = {
        record["request"]["request_id"]: record["response"]
        for record in primary
    }

    matching_responses = 0

    # Compare every replay response with its original response
    for record in replay:

        request_id = record["request"]["request_id"]

        if (
            record["status_code"] == 200
            and record["error"] is None
            and request_id in original_responses
            and record["response"] == original_responses[request_id]
        ):
            matching_responses += 1

        else:
            violations.append(
                f"{request_id}: idempotency replay mismatch"
            )

    # Number of additional allocations committed during replay
    new_allocations = 0

    # Redis counter values before and after the replay phase
    before = snapshots["after_primary"]
    after = snapshots["after_replay"]

    for campaign_id, count in after.items():

        # Ideally this difference should always be zero
        difference = count - before[campaign_id]

        new_allocations += difference

        if difference != 0:
            violations.append(
                f"Campaign {campaign_id}: "
                "allocation count changed during replay"
            )

    return {
        "replay_requests": len(replay),
        "matching_responses": matching_responses,
        "new_committed_allocations": new_allocations,
    }


# --------------------------------------------------
# Campaign capacity audit
# --------------------------------------------------

# Reconcile PostgreSQL capacity with Redis committed allocations
def audit_capacity(
    capacity_rows,
    manifest,
    snapshots,
    violations,
):

    # Store capacity breakdown for every primary campaign
    campaign_results = []

    # Aggregate capacity metrics across primary campaigns
    totals = {
        "capacity": 0,
        "unleased": 0,
        "leased": 0,
        "committed": 0,
        "unresolved_leased": 0,
        "overspend": 0,
        "lease_count": 0,
    }

    for row in capacity_rows:

        campaign_id = row["id"]
        campaign = manifest.get(campaign_id)

        # Every PostgreSQL campaign must exist in our manifest
        if campaign is None:

            violations.append(
                f"Unexpected campaign in PostgreSQL: {campaign_id}"
            )

            continue

        # Original campaign capacity
        capacity = row["capacity"]

        # Capacity still available in PostgreSQL
        unleased = row["remaining_unleased_capacity"]

        # Total capacity granted to application workers
        leased = row["granted_units"]

        # Total allocations successfully committed in Redis
        committed = snapshots["after_replay"][str(campaign_id)]

        # Leased capacity not accounted for by committed allocations
        # May include unused local inventory or burned capacity
        unresolved = leased - committed

        # Allocations exceeding the campaign's original capacity
        overspend = max(0, committed - capacity)


        # ----------------------------------------------
        # Validate capacity invariants
        # ----------------------------------------------

        # Original campaign capacity must remain unchanged
        if capacity != campaign["capacity"]:
            violations.append(
                f"Campaign {campaign_id}: original capacity changed"
            )

        # All campaigns should still be active in this workload
        if row["status"] != "ACTIVE":
            violations.append(
                f"Campaign {campaign_id}: unexpected campaign status"
            )

        # Activated campaigns must have initialized capacity
        if unleased is None:

            violations.append(
                f"Campaign {campaign_id}: missing unleased capacity"
            )

            continue

        # Original capacity must equal leased plus unleased capacity
        if capacity != unleased + leased:
            violations.append(
                f"Campaign {campaign_id}: durable lease accounting mismatch"
            )

        # PostgreSQL must never contain invalid remaining capacity
        if unleased < 0 or unleased > capacity:
            violations.append(
                f"Campaign {campaign_id}: invalid unleased capacity"
            )

        # Workers cannot commit more allocations than they were granted
        if committed < 0 or committed > leased:
            violations.append(
                f"Campaign {campaign_id}: invalid committed capacity"
            )

        # Verify that the campaign's original capacity was not exceeded
        if overspend:
            violations.append(
                f"Campaign {campaign_id}: capacity overspend"
            )


        # ----------------------------------------------
        # Aggregate primary campaign results
        # ----------------------------------------------

        # Audit warm-up campaigns but exclude them from primary metrics
        if campaign["name"].startswith("WARMUP_"):
            continue

        totals["capacity"] += capacity
        totals["unleased"] += unleased
        totals["leased"] += leased
        totals["committed"] += committed
        totals["unresolved_leased"] += unresolved
        totals["overspend"] += overspend
        totals["lease_count"] += row["lease_count"]

        # Preserve individual campaign metrics for later analysis
        campaign_results.append({
            "campaign_id": campaign_id,
            "name": row["name"],
            "capacity": capacity,
            "unleased": unleased,
            "leased": leased,
            "committed": committed,
            "unresolved_leased": unresolved,
            "overspend": overspend,
            "lease_count": row["lease_count"],

            # Number of distinct workers that obtained campaign leases
            "worker_count": row["worker_count"],
        })


    # --------------------------------------------------
    # Calculate overall capacity utilization
    # --------------------------------------------------

    if totals["capacity"] == 0:
        raise RuntimeError("No primary campaign capacity found.")

    # Percentage of original capacity successfully committed
    totals["consumption_percent"] = (
        totals["committed"] / totals["capacity"]
    ) * 100

    # Percentage of original capacity not consumed
    totals["underspend_percent"] = (
        (totals["capacity"] - totals["committed"])
        / totals["capacity"]
    ) * 100

    # Percentage of leased capacity successfully committed
    totals["lease_utilization_percent"] = (
        totals["committed"] / totals["leased"] * 100
        if totals["leased"] > 0
        else 0
    )

    return totals, campaign_results


# --------------------------------------------------
# API and Redis allocation reconciliation
# --------------------------------------------------

# Ensure returned commercial ads match committed Redis allocations
def reconcile_allocations(
    warmup_audit,
    primary_audit,
    snapshots,
    manifest,
    violations,
):

    for campaign_id, campaign in manifest.items():

        # JSON stores dictionary keys as strings
        key = str(campaign_id)

        # Calculate allocations committed during warm-up
        redis_warmup = (
            snapshots["after_warmup"][key]
            - snapshots["initial"][key]
        )

        # Calculate allocations committed during the primary burst
        redis_primary = (
            snapshots["after_primary"][key]
            - snapshots["after_warmup"][key]
        )

        # Number of commercial slots returned by the API during warm-up
        api_warmup = warmup_audit["allocations"].get(
            campaign_id, 0
        )

        # Number of commercial slots returned during the primary burst
        api_primary = primary_audit["allocations"].get(
            campaign_id, 0
        )

        # Compare API allocations with Redis committed counts
        if api_warmup != redis_warmup:
            violations.append(
                f"Campaign {campaign_id}: warm-up API/Redis mismatch"
            )

        if api_primary != redis_primary:
            violations.append(
                f"Campaign {campaign_id}: primary API/Redis mismatch"
            )

        # Warm-up traffic must not consume primary campaign capacity
        if not campaign["name"].startswith("WARMUP_"):

            if redis_warmup != 0:
                violations.append(
                    f"Campaign {campaign_id}: warm-up inventory leakage"
                )

        # Primary viewers must not receive warm-up campaigns
        elif redis_primary != 0:

            violations.append(
                f"Campaign {campaign_id}: primary inventory leakage"
            )


# --------------------------------------------------
# Complete trial audit
# --------------------------------------------------

# Coordinate all correctness and performance checks
def audit_trial(trial_number):

    trial_dir = RESULTS_DIR / f"trial_{trial_number:02d}"

    # Map campaign IDs to their original configurations
    manifest = {
        campaign["id"]: campaign
        for campaign in load_json(
            trial_dir / "campaign_manifest.json"
        )
    }

    # Load results generated by locustfile.py
    warmup = load_json(trial_dir / "warmup.json")
    primary = load_json(trial_dir / "primary.json")
    replay = load_json(trial_dir / "replay.json")

    # Load allocation counters and performance summaries
    snapshots = load_json(
        trial_dir / "redis_snapshots.json"
    )

    summaries = load_json(
        trial_dir / "summary.json"
    )

    # Collect all observed audit failures
    violations = []


    # --------------------------------------------------
    # Verify workload completeness
    # --------------------------------------------------

    # Ensure every planned request was recorded
    for records, expected in [
        (warmup, 150),
        (primary, 1000),
        (replay, 50),
    ]:

        if len(records) != expected:
            violations.append(
                f"Expected {expected} requests, found {len(records)}"
            )

    # Warm-up and primary requests must have unique request IDs
    original_ids = [
        record["request"]["request_id"]
        for record in warmup + primary
    ]

    if len(original_ids) != len(set(original_ids)):
        violations.append(
            "Duplicate request IDs in original traffic"
        )

    # Replay should contain 50 distinct original requests
    replay_ids = [
        record["request"]["request_id"]
        for record in replay
    ]

    if len(replay_ids) != len(set(replay_ids)):
        violations.append(
            "Duplicate IDs within the replay phase"
        )


    # --------------------------------------------------
    # Execute the individual audits
    # --------------------------------------------------

    # Validate all warm-up pods
    warmup_audit = audit_pods(
        warmup,
        manifest,
        violations,
    )

    # Validate all primary advertisement pods
    primary_audit = audit_pods(
        primary,
        manifest,
        violations,
    )

    # Verify idempotency across replayed requests
    replay_audit = audit_replays(
        primary,
        replay,
        snapshots,
        violations,
    )

    # Compare returned commercial ads with Redis allocations
    reconcile_allocations(
        warmup_audit,
        primary_audit,
        snapshots,
        manifest,
        violations,
    )

    # Retrieve durable capacity state before resetting the environment
    capacity_rows = load_capacity_state()

    # Preserve PostgreSQL evidence for future analysis
    (trial_dir / "postgres_snapshot.json").write_text(
        json.dumps(capacity_rows, indent=2),
        encoding="utf-8",
    )

    # Ensure PostgreSQL contains the expected campaigns
    if {row["id"] for row in capacity_rows} != set(manifest):

        violations.append(
            "PostgreSQL campaign IDs do not match manifest"
        )

    # Verify campaign-level capacity accounting
    capacity_totals, campaign_results = audit_capacity(
        capacity_rows,
        manifest,
        snapshots,
        violations,
    )


    # --------------------------------------------------
    # Calculate advertisement fill metrics
    # --------------------------------------------------

    # Total advertisement duration requested by all primary viewers
    requested_seconds = sum(
        record["request"]["break_duration_seconds"]
        for record in primary
    )

    # Percentage of requested duration filled with commercial ads
    commercial_fill_percent = (
        primary_audit["commercial_seconds"]
        / requested_seconds
    ) * 100

    primary_audit["commercial_fill_percent"] = (
        commercial_fill_percent
    )

    # Percentage of requested duration filled with house ads
    primary_audit["house_fill_percent"] = (
        primary_audit["house_seconds"]
        / requested_seconds
    ) * 100

    # Percentage explicitly returned as unfilled
    primary_audit["unfilled_percent"] = (
        primary_audit["unfilled_seconds"]
        / requested_seconds
    ) * 100

    # Duration not accounted for due to failed or invalid responses
    primary_audit["unaccounted_seconds"] = (
        requested_seconds
        - primary_audit["commercial_seconds"]
        - primary_audit["house_seconds"]
        - primary_audit["unfilled_seconds"]
    )


    # --------------------------------------------------
    # Generate the complete audit report
    # --------------------------------------------------

    report = {
        "trial": trial_number,
        "traffic_summary": summaries,

        # Performance metrics for each phase
        "warmup_latency": latency_metrics(warmup),
        "primary_latency": latency_metrics(primary),
        "replay_latency": latency_metrics(replay),

        # Correctness and advertisement delivery metrics
        "warmup_audit": warmup_audit,
        "primary_audit": primary_audit,
        "replay_audit": replay_audit,

        # Aggregate and individual campaign capacity metrics
        "capacity": capacity_totals,
        "campaign_results": campaign_results,

        # Observed audit failures
        "violation_count": len(violations),
        "violations": violations,
    }

    report_path = trial_dir / "audit_report.json"

    # Preserve the complete report before displaying results
    report_path.write_text(
        json.dumps(report, indent=2),
        encoding="utf-8",
    )


    # --------------------------------------------------
    # Display benchmark results
    # --------------------------------------------------

    print("\n========== BENCHMARK AUDIT ==========")

    print(f"Trial: {trial_number}")

    print("\nPrimary latency:")
    print(
        json.dumps(report["primary_latency"], indent=2)
    )

    print("\nCapacity accounting:")
    print(
        json.dumps(capacity_totals, indent=2)
    )

    print("\nIdempotency:")
    print(
        json.dumps(replay_audit, indent=2)
    )

    print(
        f"\nCommercial fill: "
        f"{commercial_fill_percent:.2f}%"
    )

    print(f"Violations: {len(violations)}")

    # Display every observed violation for debugging
    for violation in violations:
        print(violation)

    print(f"\nReport saved to: {report_path}")

    # Return a non-zero exit code if the audit failed
    if violations:
        raise SystemExit(1)


# --------------------------------------------------
# Script entry point
# --------------------------------------------------

if __name__ == "__main__":

    # Accept the trial number from the terminal
    parser = argparse.ArgumentParser()

    parser.add_argument(
        "--trial",
        type=int,
        required=True,
    )

    args = parser.parse_args()

    # Audit the requested benchmark trial
    audit_trial(args.trial)